<template>
  <div class="crosshair-wrap" :style="{ height: h, width: w }">
    <div
      v-for="(layer, index) in layers"
      :style="{ zIndex: layers.length + 1 - index }"
      :key="layer"
      class="crosshair-inner"
      v-show="!layer.hidden"
    >
      <Default v-if="layer.type === 1" :settings="layer" />
      <Circle v-else-if="layer.type === 2" :settings="layer" />
    </div>
  </div>
</template>

<script>
import Default from "./Types/Default/Default.vue";
import Circle from "./Types/Circle/Circle.vue";

export default {
  name: "crosshair-render",
  components: { Default, Circle },
  props: ["h", "w", "layers"],
};
</script>

<style lang="scss" scoped>
.crosshair-wrap {
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;

  .crosshair-inner {
    position: absolute;
  }
}
</style>
