<template>
  <div :class="wrap">
    <slot name="headersTop"></slot>
    <div class="headers">
      <button
        v-wave="ripple"
        v-for="tab in tabTitles"
        :key="tab.title"
        :class="['header', { selected: tab.title === selectedTitle }]"
        @click="clickHandle(tab.title)"
      >
        <div class="inner">
          <div v-if="tab.icon" class="icon">
            <i :class="tab.icon"></i>
          </div>
          <div class="title">{{ tab.title }}</div>
        </div>
      </button>
    </div>
    <slot name="headersBottom"></slot>
    <div class="content">
      <slot />
    </div>
  </div>
</template>

<script>
import { ref, provide } from "vue";

export default {
  name: "TabsWrapper",
  props: {
    wrap: {
      type: String,
    },
    ripple: {
      type: Boolean,
      default: true,
    },
  },
  setup(props, { slots }) {
    let tabs = slots
      .default()
      .filter((tab) => tab.props)
      .map((tab) => tab.props);
    slots.default().forEach((tab) => {
      if (!Array.isArray(tab.children)) return;
      tabs = tabs.concat(tab.children.map((tab) => tab.props));
    });

    const tabTitles = ref(tabs);

    const selectedTitle = ref(tabTitles.value[0].title);

    provide("selectedTitle", selectedTitle);
    provide("tabTitles", tabTitles);
    return {
      selectedTitle,
      tabTitles,
    };
  },
  methods: {
    clickHandle(title) {
      this.selectedTitle = title;
    },
  },
};
</script>
